SELECT sku_id
FROM tb_order
WHERE sku_id IS NOT NULL
  AND status IN (1, 2)
   AND region_id = #{query.regionId}
   AND business_type = #{query.businessType}
   AND partner_id = #{query.partnerId}
   AND node_id = #{query.nodeId}
  AND EXISTS (
      SELECT 1 FROM tb_channel available_channel
      WHERE available_channel.sku_id = tb_order.sku_id
        AND available_channel.current_capacity > 0

          AND available_channel.inner_code = #{query.innerCode}

  )
GROUP BY sku_id
ORDER BY SUM(quantity) DESC
LIMIT #{query.resolveLimit}
